import sys
import tarfile


archive_path, output_path = sys.argv[1:3]
report = {}
with tarfile.open(archive_path, "r:gz") as archive:
    members = {member.name: member for member in archive.getmembers() if member.isfile()}
    report["files"] = {name: member.size for name, member in sorted(members.items())}
    for name in sorted(members):
        if name.endswith(".psam") or name.endswith(".csv"):
            handle = archive.extractfile(members[name])
            report[name] = handle.read().decode("utf-8", errors="replace").splitlines()
        elif name.endswith(".pvar"):
            handle = archive.extractfile(members[name])
            lines = io.TextIOWrapper(handle, encoding="utf-8", errors="replace")
            first = []
            variants = 0
            for line in lines:
                if len(first) < 8:
                    first.append(line.rstrip("\n"))
                if not line.startswith("#"):
                    variants += 1

